from datetime import datetime,timezone
from pathlib import Path
import json,statistics
root=Path(__file__).resolve().parent.parent;protocol=json.loads((root/'milestone-29-protocol.json').read_text());done=(root/'milestone-29-summary.json').exists();f=root/('milestone-29-summary.json' if done else 'milestone-29-progress.json');rs=json.loads(f.read_text()) if f.exists() else []
lines=['# Milestone 29 — corrected aerodynamic computation cost','','**Status: '+('complete' if done else 'pending or running')+'.**','','This study measures the actual local-flocking, rigid-body, contact and corrected airflow pipeline for one simulated second. It is run serially after the long mission studies have ended. Three timing repeats use the same initial scene; they are not independent mission trials. Rendering is separate.','','|Drones|Model|Runs|Full windows|Median total wall s|Median airflow s|Median steering s|Median physics s|Median safety s|Median measurement s|','|---:|---|---:|---:|---:|---:|---:|---:|---:|---:|']
groups=[]
for n in [50,200,1000,5000]:
 for mode in ['off','sum-force','sum-rotor','rss-rotor']:
  group=[r for r in rs if r['job']['count']==n and r['job']['aeroMode']==mode];full=[r for r in group if abs(r['metrics']['end']-1)<1e-9 and not r['metrics']['stopReason']];row={'count':n,'model':mode,'runs':len(group),'fullWindows':len(full)}
  # Do not advertise the wall time of an early exit as a full-window result.
  for k in ['total','aerodynamics','steering','physics','safety','measurement']:
   row[k]=statistics.median(r['timing'].get(k,0) for r in full)/1000 if full else None
  row['fullWindowTotalSeconds']=[r['timing']['total']/1000 for r in full];row['allMeasuredTotalSeconds']=[r['timing']['total']/1000 for r in group];row['recordedEndSeconds']=[r['metrics']['end'] for r in group];groups.append(row);lines.append(f'|{n}|{mode}|{len(group)}|{len(full)}|'+ '|'.join(('no full window' if group else 'pending') if row[k] is None else f'{row[k]:.5f}' for k in ['total','aerodynamics','steering','physics','safety','measurement'])+'|')
lines+=['','## Repeat variation','','Three repetitions of one scene describe runtime variation, not independent mission reliability. Full-window values below are listed in repeat order. Differences can reflect operating-system load, thermal state and partially warmed JIT execution.','','|Drones|Model|Full-window wall seconds, each repeat|','|---:|---|---|']
for row in groups:lines.append(f"|{row['count']}|{row['model']}|"+(', '.join(f'{t:.5f}' for t in row['fullWindowTotalSeconds']) or 'no completed full windows')+'|')
lines+=['','## Early stops and missing full windows','','|Case|Simulated end s|Stop|Measured work wall s|','|---|---:|---|---:|']
for r in rs:
 if r['metrics']['stopReason'] or abs(r['metrics']['end']-1)>1e-9:lines.append(f"|{r['job']['id']}|{r['metrics']['end']:.5f}|{r['metrics']['stopReason']}|{r['timing']['total']/1000:.5f}|")
lines+=['','Shorter stopped windows are incomplete workloads, not speedup evidence.','','## Interpretation','','Each child gets a short development warmup, excluded from timing. Startup, module loading and final serialization are excluded. In-memory recording and scientific measurement are included. Background operating-system load and thermal state remain uncontrolled. An [opportunistic host-load observation](milestone-29-host-load-observations.json) provides context but cannot identify the cause of timing variation. Model order rotates over repeats. Raw individual times and stop reasons remain in the results.','','This is a one-second startup-window cost comparison, before the first wall. It does not measure crowded doorway cost, completed missions, aerodynamic accuracy, GPU execution or live browser physics. The Three.js page replays the recorded windows. Different recording and timestep settings from milestone25 preclude a direct optimization-speedup claim.','','Force-only and rotor-moment models use the corrected opposite-motor wake length. Their assumptions remain exploratory; faster computation does not imply adequate physical fidelity.','',f'Saved {len(rs)}/{len(protocol["jobs"])} prescribed runs.','', '[3D replay](milestone-29-lab.html) · [Runtime environment](milestone-29-runtime.json) · [Protocol](milestone-29-protocol.json) · [Raw results](milestone-29-progress.json) · [Corrected mission study](milestone-28-report.md) · [Earlier rendering measurements](milestone-25-rendering.json).','']
lines[2:2]=['Generated: '+datetime.now(timezone.utc).isoformat(timespec='seconds')+' (UTC).','']
(root/'milestone-29-report.md').write_text('\n'.join(lines));(root/'milestone-29-costs.json').write_text(json.dumps({'studyComplete':done,'groups':groups},indent=2));print({'runs':len(rs),'complete':done})
